<template><section class="pro-panel"><span class="eyebrow">Public profile</span><h1>{{tipster?.username||'Your profile'}}</h1><p>{{tipster?.bio||'Add a clear football bio so members know what your selections specialise in.'}}</p><div class="td-mini-stats"><div><span>Country</span><b>{{tipster?.country||'Global'}}</b></div><div><span>Expertise</span><b>{{tipster?.expertise||'Football analysis'}}</b></div><div><span>Win rate</span><b>{{winRate}}%</b></div><div><span>Total tips</span><b>{{tipster?.totalTips||0}}</b></div></div><RouterLink v-if="tipster?.username" :to="`/tipsters/${encodeURIComponent(tipster.username)}`" class="btn">Open public profile →</RouterLink></section></template><script setup lang="ts">import{computed,onMounted,ref}from'vue';import{RouterLink}from'vue-router';import{api}from'../services/api';const tipster=ref<any>(null);const winRate=computed(()=>{const w=Number(tipster.value?.wins||0),l=Number(tipster.value?.losses||0);return w+l?Math.round(w/(w+l)*100):0});onMounted(async()=>{try{tipster.value=(await api.get('/me/tipster')).data.profile}catch{}})</script>
